CREATE TABLE IF NOT EXISTS source (source_id  INTEGER       AUTO_INCREMENT, name       VARCHAR(100)  BINARY NOT NULL, type       VARCHAR(50)  NOT NULL, url        TEXT  NULL, provider   VARCHAR(250)  NULL, date       VARCHAR(50)   NULL, author     VARCHAR(50)   NULL, domain     VARCHAR(50)   NULL, version    VARCHAR(50)   NULL, comment    TEXT  NULL, status     VARCHAR(50)  NULL, PRIMARY KEY(source_id))  ENGINE = InnoDB;
CREATE TABLE IF NOT EXISTS source_rel (sourcerel_id   INTEGER      AUTO_INCREMENT, source1_id     INTEGER      NOT NULL, source2_id     INTEGER      NOT NULL, type           INTEGER  NOT NULL, name           VARCHAR(100) NULL, comment        TEXT NULL, provider       VARCHAR(250) NULL, preprocessing  INTEGER NULL, date           VARCHAR(50)  NULL, status  VARCHAR(50) NULL, PRIMARY KEY(sourcerel_id),UNIQUE(source1_id, source2_id, type, name))  ENGINE = InnoDB;
CREATE TABLE IF NOT EXISTS object (object_id   INTEGER      AUTO_INCREMENT, source_id   INTEGER      NOT NULL, accession   VARCHAR(250) BINARY NOT NULL, name TEXT NULL, type        VARCHAR(100) NULL, typespace   VARCHAR(100) NULL, kind        INTEGER NULL, comment     TEXT NULL, synonyms    VARCHAR(500) NULL, PRIMARY KEY(object_id), UNIQUE(source_id, accession, kind), INDEX(source_id), INDEX(accession))  ENGINE = InnoDB;
CREATE TABLE IF NOT EXISTS object_rel (sourcerel_id INTEGER      NOT NULL, object1_id   INTEGER      NOT NULL, object2_id   INTEGER      NOT NULL, similarity   FLOAT   NULL, type         VARCHAR(50)  NULL, UNIQUE(sourcerel_id, object1_id, object2_id), INDEX(sourcerel_id), INDEX(object1_id), INDEX(object2_id))  ENGINE = InnoDB;
CREATE TABLE IF NOT EXISTS workflow (name       VARCHAR(100)  BINARY NOT NULL, value      TEXT  NULL, PRIMARY KEY(name))  ENGINE = InnoDB;
